{
  "lines": [
    {
      "key": "opening",
      "japanese": "あれ、〇〇じゃん！久しぶり！",
      "reading": "あれ、まるまるじゃん！ひさしぶり！",
      "romaji": "Are, marumaru jan! Hisashiburi! (Hey, it's [Name]! Long time no see!)"
    },
    {
      "key": "reply",
      "japanese": "あ、〇〇！本当、久しぶり！元気だった？",
      "reading": "あ、まるまる！ほんとう、ひさしぶり！げんきだった？",
      "romaji": "A, marumaru! Hontou, hisashiburi! Genki datta? (Oh, [Name]! Really, long time no see! How have you been?)"
    },
    {
      "key": "ask_plans",
      "japanese": "うん、まあまあかな。ところで、今日って何か予定ある？",
      "reading": "うん、まあまあかな。ところで、きょうってなにかよていある？",
      "romaji": "Un, maa maa kana. Tokoro de, kyou tte nani ka yotei aru? (Yeah, I'm okay. By the way, do you have any plans today?)"
    },
    {
      "key": "suggest_outing",
      "japanese": "もし暇だったら、ちょっと飲みに行かない？",
      "reading": "もしひまだったら、ちょっとのみにいかない？",
      "romaji": "Moshi hima dattara, chotto nomi ni ikanai? (If you're free, wanna go for a drink?)"
    },
    {
      "key": "accept_outing",
      "japanese": "いいね！行こう行こう！",
      "reading": "いいね！いこういこう！",
      "romaji": "Ii ne! Ikou ikou! (Sounds good! Let's go, let's go!)"
    },
    {
      "key": "confirm_time",
      "japanese": "何時くらいがいいかな？",
      "reading": "なんじくらいがいいかな？",
      "romaji": "Nanji kurai ga ii kana? (Around what time would be good?)"
    },
    {
      "key": "propose_time",
      "japanese": "７時とかどう？",
      "reading": "しちじとかどう？",
      "romaji": "Shichiji toka dou? (How about 7 o'clock?)"
    },
    {
      "key": "agree_time",
      "japanese": "うん、大丈夫！じゃあ、また後で！",
      "reading": "うん、だいじょうぶ！じゃあ、またあとで！",
      "romaji": "Un, daijoubu! Jaa, mata ato de! (Yeah, that's fine! Well then, see you later!)"
    },
    {
      "key": "closing",
      "japanese": "またね！",
      "reading": "またね！",
      "romaji": "Mata ne! (See ya!)"
    }
  ]
}

